echo 'class BloomFilter {
  constructor(size = 1000, numHashes = 3) {
    this.size = size;
    this.numHashes = numHashes;
    this.bitArray = new Array(size).fill(0);
  }

  // Simple hash functions
  hash1(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash * 31 + str.charCodeAt(i)) % this.size;
    }
    return hash;
  }

  hash2(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash * 37 + str.charCodeAt(i)) % this.size;
    }
    return hash;
  }

  hash3(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash * 41 + str.charCodeAt(i)) % this.size;
    }
    return hash;
  }

  // Get all hash values for a string
  getHashes(str) {
    const hashes = [];
    hashes.push(this.hash1(str));
    hashes.push(this.hash2(str));
    if (this.numHashes >= 3) hashes.push(this.hash3(str));
    return hashes;
  }
}' > bloom.js

echo '
  // Add an element to the filter
  add(str) {
    const hashes = this.getHashes(str);
    for (const hash of hashes) {
      this.bitArray[hash] = 1;
    }
  }

  // Check if an element might be in the filter
  mightContain(str) {
    const hashes = this.getHashes(str);
    for (const hash of hashes) {
      if (this.bitArray[hash] === 0) {
        return false; // Definitely not in the set
      }
    }
    return true; // Might be in the set
  }
}' >> bloom.js

echo '
// Example usage
const filter = new BloomFilter(1000, 3);

// Add some file paths
filter.add("src/main.c");
filter.add("docs/guide.md");
filter.add("src/utils/helper.c");

// Check if paths exist
console.log("src/main.c exists?", filter.mightContain("src/main.c")); // true
console.log("docs/guide.md exists?", filter.mightContain("docs/guide.md")); // true
console.log("src/utils/helper.c exists?", filter.mightContain("src/utils/helper.c")); // true
console.log("src/utils/math.c exists?", filter.mightContain("src/utils/math.c")); // probably false, but might be true (false positive)
' >> bloom.js

echo '
// Test with more paths
const paths = [
  "src/main.c",
  "docs/guide.md",
  "src/utils/helper.c",
  "src/utils/string.c",
  "src/utils/memory.c",
  "include/header.h",
  "tests/test_main.c",
  "build/output.o",
  "README.md",
  ".gitignore"
];

// Create a smaller filter to increase chance of false positives
const smallFilter = new BloomFilter(50, 3);

// Add the paths
for (const path of paths) {
  smallFilter.add(path);
}

// Test existing paths
console.log("\nTesting existing paths:");
for (const path of paths) {
  console.log(`${path} exists? ${smallFilter.mightContain(path)}`);
}

// Test non-existing paths
console.log("\nTesting non-existing paths:");
const nonExistingPaths = [
  "src/utils/math.c",
  "docs/api.md",
  "src/main.h",
  "tests/test_utils.c",
  "build/debug.o"
];

let falsePositives = 0;
for (const path of nonExistingPaths) {
  const result = smallFilter.mightContain(path);
  console.log(`${path} exists? ${result}`);
  if (result) falsePositives++;
}

console.log(`\nFalse positive rate: ${falsePositives / nonExistingPaths.length * 100}%`);
' >> bloom.js
